import functools

# 1. __repr__ 和 __str__：开发者调试 vs 用户输出
@functools.total_ordering
class Point:
    """二维坐标，支持比较和哈希。"""
    __slots__ = ('x', 'y')  # 节省内存，禁止动态属性

    def __init__(self, x, y):
        self.x = x
        self.y = y

    def __repr__(self):
        # !r 确保嵌套类型也走 repr；eval('Point(3, 5)') 能重建对象
        return f"Point({self.x!r}, {self.y!r})"

    def __str__(self):
        return f"({self.x}, {self.y})"

    def __eq__(self, other):
        if not isinstance(other, Point):
            return NotImplemented  # 告知 Python 尝试反向比较
        return self.x == other.x and self.y == other.y

    def __lt__(self, other):
        if not isinstance(other, Point):
            return NotImplemented
        return (self.x, self.y) < (other.x, other.y)

    def __hash__(self):
        return hash((self.x, self.y))  # 与 __eq__ 使用相同字段

    def __add__(self, other):
        if not isinstance(other, Point):
            return NotImplemented
        return Point(self.x + other.x, self.y + other.y)

    def __neg__(self):
        return Point(-self.x, -self.y)

p1 = Point(3, 5)
p2 = Point(3, 5)
print(repr(p1))           # Point(3, 5)
print(str(p1))            # (3, 5)
print(p1 == p2)           # True
print(hash(p1) == hash(p2))  # True
print(p1 + p2)            # (6, 10)
print(-p1)                # (-3, -5)
print({p1: 'found'}[p2])  # found —— 相等对象可以互换作为 key


# 2. __call__：策略对象、缓存
class Memoize:
    """简单函数缓存装饰器类。"""
    def __init__(self, func):
        self.func = func
        self.cache = {}

    def __call__(self, *args):
        if args not in self.cache:
            self.cache[args] = self.func(*args)
        return self.cache[args]

@Memoize
def fibonacci(n):
    if n < 2:
        return n
    return fibonacci(n - 1) + fibonacci(n - 2)

print(fibonacci(30))  # 832040，利用缓存快速计算


# 3. __enter__ / __exit__：资源管理
class Timer:
    """上下文管理器，测量代码块执行时间。"""
    def __enter__(self):
        import time
        self.start = time.perf_counter()
        return self  # 返回 self，通过 as 变量访问

    def __exit__(self, exc_type, exc_val, exc_tb):
        import time
        self.elapsed = time.perf_counter() - self.start
        return False  # 不吞异常

with Timer() as t:
    sum(range(1_000_000))
print(f"elapsed: {t.elapsed:.4f}s")


# 4. __getitem__ 容器：切片、in、for 隐式支持
class Cycle:
    """循环缓冲区，支持下标、切片、成员检测和迭代。"""
    def __init__(self, *items):
        self._data = list(items)

    def __getitem__(self, key):
        if isinstance(key, slice):
            # 切片时返回普通 list
            return self._data[key]
        return self._data[key % len(self._data)]

    def __len__(self):
        return len(self._data)

    def __contains__(self, item):
        return item in self._data

c = Cycle(10, 20, 30)
print(c[0], c[3])     # 10 10 —— 循环访问
print(20 in c)        # True
print(list(c))        # [10, 20, 30] —— 只有 __getitem__ 就能迭代
